/* nos_fonts.h - NOS proportional type (generated by tools/bake_font.py --nos).
 *
 * House pairing: Space Grotesk (grotesk; NType 82 stand-in) for numbers, titles and
 * body, Space Mono (Lettera Mono stand-in) for ALL-CAPS labels. Both SIL OFL 1.1,
 * sources + licences in third_party/fonts/. Draw with font_draw() (core/font.h):
 * pen at (x, baseline). The degree sign is the single byte "\xB0" (Latin-1), as in
 * core/fonts; "\xB7" is a middot.
 *
 * Sizes are em px on the 466 px, 326 ppi panel (12.8 px/mm):
 *   nf_hero    Space Grotesk Regular 160 px: full-screen clock, cap 112 px (8.7 mm); HH:MM is 432 px wide
 *   nf_display Space Grotesk Medium 64 px: big values, cap 45 px (3.5 mm)
 *   nf_title   Space Grotesk Medium 32 px: screen titles, cap 22 px (1.75 mm)
 *   nf_body    Space Grotesk Regular 26 px: body text, cap 18 px (1.4 mm), x-height 13 px
 *   nf_label   Space Mono Regular 18 px: ALL-CAPS labels, cap 13 px, +0.06 em tracking
 *   nf_small   Space Mono Regular 15 px: ALL-CAPS micro text, cap 10.5 px, +0.07 em tracking
 * Digits are tabular in nf_hero and nf_display (ticking values never jitter).
 * nf_label / nf_small have letter-spacing baked into their advances. */
#ifndef NOS_FONTS_H
#define NOS_FONTS_H
#include "font.h"

extern const font_t nf_hero;
extern const font_t nf_display;
extern const font_t nf_title;
extern const font_t nf_body;
extern const font_t nf_label;
extern const font_t nf_small;
#endif
